const input = $json.body ?? $json;
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const channel = String(input.channel ?? input.preferred_channel ?? 'sms').toLowerCase();
const attempt = Number(input.attempt_number ?? input.reengagement_attempts ?? 1);
const cadence = input.cadence ?? (attempt === 1 ? '24h' : attempt === 2 ? '72h' : '7d');
const dnc = Boolean(input.dnc ?? input.do_not_contact);
const phone = input.phone ?? input.mobile_phone ?? null;
const email = input.email ?? null;
const sellerName = input.seller_name ?? input.first_name ?? 'there';
const propertyAddress = input.property_address ?? input.address ?? 'the property';
const reason = input.reason ?? input.negotiation_outcome ?? 'our recent conversation';
const lastOffer = Number(input.last_offer_price ?? input.offer_price);
const askingPrice = Number(input.asking_price);
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const identityOk = Boolean(dealId && leadId && propertyId);
const recipientOk = channel === 'sms' ? Boolean(phone) : channel === 'email' ? Boolean(email) : false;
const eligible = identityOk && recipientOk && !dnc;

let message = '';
if (attempt <= 1) {
  message = channel === 'email'
    ? `Hi ${sellerName}, I wanted to circle back about ${propertyAddress}. I know we weren't able to get something finalized earlier, but I'm still interested in finding a number that makes sense for you. If you're open to it, what would you need to make a deal work?`
    : `Hi ${sellerName}, just circling back about ${propertyAddress}. I know we couldn't get something finalized earlier, but I'm still interested. If you're open to it, what would you need to make a deal work?`;
} else if (attempt === 2) {
  message = channel === 'email'
    ? `Hi ${sellerName}, following up once more on ${propertyAddress}. If your plans have changed, I'm happy to revisit the numbers and see if there's a way to make this work. Want to talk through it?`
    : `Hi ${sellerName}, following up once more on ${propertyAddress}. If your plans changed, I'm happy to revisit the numbers and see if we can make this work. Want to talk through it?`;
} else {
  message = channel === 'email'
    ? `Hi ${sellerName}, I'll close the loop for now on ${propertyAddress}. If you'd like to revisit the sale later, feel free to reach back out and I'll be happy to take another look.`
    : `Hi ${sellerName}, I'll close the loop for now on ${propertyAddress}. If you want to revisit the sale later, just reach back out and I'll take another look.`;
}

const dispatchId = 'WF-262:' + (dealId ?? leadId ?? 'unknown') + ':attempt:' + attempt;
const idempotencyKey = dispatchId + ':' + channel;
const dispatchReady = eligible && message.length > 0 && channel !== 'unknown';

return [{ json: {
  ...input,
  workflow_id: 'WF-262',
  workflow_name: 'Seller Re-engagement Message Generation & Dispatch Controller',
  status: dispatchReady ? 'dispatch_ready' : dnc ? 'do_not_contact' : 'blocked',
  dispatch_ready: dispatchReady,
  human_review_required: false,
  channel,
  recipient: channel === 'sms' ? phone : email,
  message,
  message_context: {
    seller_name: sellerName,
    property_address: propertyAddress,
    reason,
    attempt_number: attempt,
    cadence,
    last_offer_price: Number.isFinite(lastOffer) ? lastOffer : null,
    asking_price: Number.isFinite(askingPrice) ? askingPrice : null,
    dynamic_mao: Number.isFinite(dynamicMao) ? dynamicMao : null
  },
  dispatch: {
    dispatch_id: dispatchId,
    idempotency_key: idempotencyKey,
    delivery_receipt_required: true,
    provider: input.provider ?? 'configured_communication_provider'
  },
  identity_valid: identityOk,
  recipient_valid: recipientOk,
  contact_suppressed: dnc,
  next_workflow: dispatchReady ? 'WF-263' : 'WF-126',
  crm_activity: {
    activity_type: 'seller_reengagement_message_prepared',
    workflow_id: 'WF-262',
    status: dispatchReady ? 'dispatch_ready' : dnc ? 'do_not_contact' : 'blocked',
    dispatch_id: dispatchId,
    channel,
    attempt_number: attempt
  }
} }];
